import { PercentPipe } from '@angular/common';
import { Component, computed, input, output } from '@angular/core';
import { HlmAvatar, HlmAvatarFallback } from '@spartan-ng/helm/avatar';
import { HlmBadge, type BadgeVariants } from '@spartan-ng/helm/badge';
import { HlmButton } from '@spartan-ng/helm/button';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero, HeroStatus } from '../../domain/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

type BadgeVariant = NonNullable<BadgeVariants['variant']>;

// Each status gets its own semantic badge; MIA is the destructive one.
const STATUS_BADGE: Record<HeroStatus, BadgeVariant> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

@Component({
  selector: 'app-hero-card',
  imports: [PercentPipe, HlmCardImports, HlmBadge, HlmButton, HlmAvatar, HlmAvatarFallback, PowerMeter],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();
  readonly opened = output<Hero>();

  protected readonly initials = computed(() =>
    this.hero()
      .alias.split(' ')
      .slice(0, 2)
      .map((part) => part.charAt(0))
      .join('')
      .toUpperCase(),
  );
  protected readonly statusVariant = computed(() => STATUS_BADGE[this.hero().status]);
}
<div hlmCard class="hero-card">
  <div hlmCardHeader class="hero-card__header">
    <hlm-avatar size="lg">
      <span hlmAvatarFallback>{{ initials() }}</span>
    </hlm-avatar>
    <div class="hero-card__identity">
      <h3 hlmCardTitle class="hero-card__name">{{ hero().name }}</h3>
      <p hlmCardDescription>{{ hero().alias }}</p>
    </div>
  </div>

  <div hlmCardContent class="hero-card__body">
    <div class="hero-card__badges">
      <span hlmBadge variant="outline">{{ hero().powerClass }}</span>
      <span hlmBadge [variant]="statusVariant()">{{ hero().status }}</span>
    </div>
    <app-power-meter [value]="hero().powerIndex" [label]="hero().name + ' power index'" />
    <p hlmCardDescription>
      {{ hero().missionCount }} missions, {{ hero().successRate | percent: '1.0-0' }} success
    </p>
  </div>

  <div hlmCardFooter class="hero-card__footer">
    <span class="hero-card__clearance">Clearance {{ hero().clearanceTier }}</span>
    <button
      hlmBtn
      variant="outline"
      size="sm"
      type="button"
      [attr.aria-label]="'Open dossier for ' + hero().name"
      (click)="opened.emit(hero())"
    >
      Dossier
    </button>
  </div>
</div>
@reference "../../../styles.css";

:host { @apply block min-w-0; }
.hero-card { @apply h-full; }
.hero-card__header { @apply flex items-center gap-3; }
.hero-card__identity { @apply grid min-w-0 gap-0.5; }
.hero-card__name { @apply truncate; }
.hero-card__body { @apply grid gap-3; }
.hero-card__badges { @apply flex flex-wrap items-center gap-1.5; }
.hero-card__footer { @apply flex flex-wrap items-center justify-between gap-2; }
.hero-card__clearance { @apply text-xs text-muted-foreground; }

